<script setup lang="ts">import {Head,useForm,router} from '@inertiajs/vue3';import AdminLayout from '@core/Layouts/AdminLayout.vue';import {Button} from '@/components/ui/button';import {Input} from '@/components/ui/input';import {Label} from '@/components/ui/label';import DataTable,{type DataTableColumn} from '@core/Components/DataTable.vue';import type {Paginator} from '@core/types';const p=defineProps<{policies:any[];runs:Paginator<any>;defaultYear:number;defaultMonth:number}>();const policy=useForm({name:'Festival Bonus',calculation_type:'percentage',amount:100,calculation_base:'basic',minimum_service_months:0,bonuses_per_year:2});const run=useForm({festival_bonus_policy_id:'',pay_year:p.defaultYear,pay_month:p.defaultMonth});function savePolicy(){policy.post(route('payroll.bonuses.policies.store'))}function generate(){run.post(route('payroll.bonuses.generate'))}function release(id:number){router.post(route('payroll.bonuses.release',id),{},{preserveScroll:true})}const runColumns:DataTableColumn[]=[{key:'period',label:'Period'},{key:'policy',label:'Policy'},{key:'employee_count',label:'Employees'},{key:'total_amount',label:'Total',align:'right'},{key:'status',label:'Status'},{key:'actions',label:'',align:'right',exportable:false}];</script><template><AdminLayout :breadcrumbs="[{ title: 'Payroll' }, { title: 'Festival Bonuses' }]"><Head title="Festival bonuses"/><div class="grid gap-6 xl:grid-cols-[380px_1fr]"><div class="space-y-5"><section class="rounded-xl border bg-card p-5"><h1 class="text-xl font-bold">Bonus policy</h1><form @submit.prevent="savePolicy" class="mt-4 space-y-3"><div><Label>Policy name</Label><Input v-model="policy.name"/></div><div class="grid grid-cols-2 gap-3"><div><Label>Type</Label><select v-model="policy.calculation_type" class="h-10 w-full rounded-md border bg-background px-3"><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></div><div><Label>Value</Label><Input v-model.number="policy.amount" type="number" min="0" step="0.01"/></div></div><div><Label>Based on</Label><select v-model="policy.calculation_base" class="h-10 w-full rounded-md border bg-background px-3"><option value="basic">Basic salary</option><option value="gross">Gross salary</option></select></div><div class="grid grid-cols-2 gap-3"><div><Label>Min service (months)</Label><Input v-model.number="policy.minimum_service_months" type="number" min="0"/></div><div><Label>Runs per year</Label><Input v-model.number="policy.bonuses_per_year" type="number" min="1" max="12"/></div></div><Button :disabled="policy.processing">Save policy</Button></form></section><section class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Generate bonus run</h2><form @submit.prevent="generate" class="mt-4 space-y-3"><div><Label>Policy</Label><select v-model="run.festival_bonus_policy_id" class="h-10 w-full rounded-md border bg-background px-3"><option value="">Select policy</option><option v-for="x in policies" :key="x.id" :value="x.id">{{x.name}}</option></select></div><div class="grid grid-cols-2 gap-3"><div><Label>Year</Label><Input v-model.number="run.pay_year" type="number"/></div><div><Label>Month</Label><Input v-model.number="run.pay_month" type="number" min="1" max="12"/></div></div><Button :disabled="run.processing">Generate run</Button></form></section></div><section class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Bonus policies</h2><div class="mt-3 divide-y"><p v-for="x in policies" :key="x.id" class="flex justify-between py-2 text-sm"><span>{{x.name}}</span><span>{{x.calculation_type==='percentage'?`${x.amount}%`:x.amount}} · min {{x.minimum_service_months}} months</span></p></div><h2 class="mt-6 font-semibold">Generated runs</h2><DataTable class="mt-3" route-name="payroll.bonuses.index" title="Bonus runs" :columns="runColumns" :rows="runs.data" :meta="runs.meta"><template #cell-period="{row}">{{row.pay_year}}-{{String(row.pay_month).padStart(2,'0')}}</template><template #cell-policy="{row}">{{row.policy?.name}}</template><template #cell-total_amount="{row}">{{Number(row.total_amount).toLocaleString()}}</template><template #cell-status="{row}">{{row.status}}</template><template #cell-actions="{row}"><Button v-if="row.status==='generated'" size="sm" @click="release(Number(row.id))">Release</Button></template></DataTable></section></div></AdminLayout></template>